                for (int a = -3; a <= 2; ++a) m_world->setBlock(bx + a, by, bz, Blocks::OakFence);
                for (int b = 1; b <= 3; ++b) m_world->setBlock(bx + 2, by, bz - b, Blocks::OakFence);
                m_world->setBlock(bx + 4, by, bz + 1, Blocks::OakFence);
