                const int bx = static_cast<int>(std::floor(ahead.x));
                const int by = static_cast<int>(std::floor(m_player.position.y));
                const int bz = static_cast<int>(std::floor(ahead.z));

                for (int i = 0; i < 3; ++i)
                    for (int k = 0; k < 2; ++k)
                        m_world->setBlock(bx + i - 1, by + k, bz, Blocks::Tnt);

